//! THE WIRE CONTRACT — the only thing the client and server both know.
//!
//! The browser's copy of these types is generated by ts-rs into
//! `web/src/generated/`, so adding a field to `RoomView`/`SyncResponse` touches
//! this file and nothing else. `room` builds these, the Worker returns them over
//! HTTP, and the room's WebSockets push them. One shape, so a move that arrives
//! by push and a move that arrives in a response cannot be handled differently
//! by accident.

use kaboo_engine::{EngineError, EngineEvent, PlayerId, Projection};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

pub type Millis = i64;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct RosterEntry {
    pub id: PlayerId,
    pub name: String,
    #[ts(type = "number")]
    pub joined_at: Millis,
}

/// What one player is entitled to see, right now.
///
/// Two shapes because the game has two states and they share no fields: before
/// the deal there are no hands at all, and after it there is no roster to show.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "status", rename_all = "camelCase", rename_all_fields = "camelCase")]
#[ts(export)]
pub enum RoomView {
    Lobby {
        code: String,
        /// Who this device is. The client verifies this against its stored session.
        you: PlayerId,
        /// Whether *you* are the host, for showing the deal button.
        host: bool,
        /// Who the host is, for labelling somebody else's row. Sent rather than
        /// inferred from `roster[0]`, which is the host only by an ordering accident.
        host_id: PlayerId,
        roster: Vec<RosterEntry>,
        seats: usize,
    },
    Playing {
        code: String,
        you: PlayerId,
        host: bool,
        /// Already projected for `you`. Never the raw GameState.
        view: Box<Projection>,
    },
}

impl RoomView {
    pub fn you(&self) -> &str {
        match self {
            RoomView::Lobby { you, .. } | RoomView::Playing { you, .. } => you,
        }
    }

    pub fn projection(&self) -> Option<&Projection> {
        match self {
            RoomView::Playing { view, .. } => Some(view),
            RoomView::Lobby { .. } => None,
        }
    }
}

/// A private event, with the sequence number that identifies it.
///
/// The seq is not decoration. A push and a response are two independent paths
/// to the same fact, and the server deliberately sends the WHOLE queue on a
/// push — it does not know what the client has already seen. With a per-event
/// seq the client keeps one cursor and dedupes exactly.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct DeliveredEvent {
    #[serde(flatten)]
    pub event: EngineEvent,
    pub seq: u32,
}

/// The response to every room read and every action, and the body of every push.
///
/// `events` carries ONLY private events addressed to this player — a peek, the
/// card received in a Queen swap, the last card of the pile. Public events are
/// not repeated here because they already reach the client through
/// `view.log`, and shipping the same fact twice is how one copy quietly drifts
/// into carrying more than it should.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SyncResponse {
    pub room: RoomView,
    pub events: Vec<DeliveredEvent>,
    /// Monotonic across the whole room. Pass the last value back as `since`.
    pub event_seq: u32,
}

/// A sync plus, when the engine refused the action, the reason — with the
/// current state, because a refused move still tells the client its view was stale.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ActionResult {
    #[serde(flatten)]
    pub sync: SyncResponse,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub refusal: Option<EngineError>,
}

/// What `POST /api/rooms` and `POST /api/rooms/:code/join` hand back.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Seated {
    pub code: String,
    /// The session. It IS the seat: keep it, and send it in `x-kaboo-session`.
    pub token: String,
    pub player_id: PlayerId,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum RoomErrorCode {
    #[serde(rename = "E_NOT_FOUND")]
    NotFound,
    #[serde(rename = "E_ROOM_FULL")]
    RoomFull,
    #[serde(rename = "E_ALREADY_STARTED")]
    AlreadyStarted,
    #[serde(rename = "E_BAD_SESSION")]
    BadSession,
    #[serde(rename = "E_BAD_REQUEST")]
    BadRequest,
    /// Not the client's fault and worth retrying.
    #[serde(rename = "E_BUSY")]
    Busy,
}

/// A rejection. The message is deliberately generic and identical in tone to
/// the engine's: a rejection reason is itself information, so no response ever
/// explains itself and the client renders one flat sentence.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct RoomError {
    #[ts(type = "false")]
    pub ok: bool,
    pub code: RoomErrorCode,
    pub message: String,
}

pub fn room_error_message(code: RoomErrorCode) -> &'static str {
    match code {
        RoomErrorCode::NotFound => "That room is not open.",
        RoomErrorCode::RoomFull => "That room is full.",
        RoomErrorCode::AlreadyStarted => "That game has already started.",
        RoomErrorCode::BadSession => "That seat is not yours.",
        RoomErrorCode::BadRequest => "That did not work.",
        RoomErrorCode::Busy => "The table is busy. Try again.",
    }
}

pub fn room_error(code: RoomErrorCode) -> RoomError {
    RoomError { ok: false, code, message: room_error_message(code).to_string() }
}

/// The HTTP status for a rejection. A refused MOVE is not here: it is a 200
/// carrying `refusal`, because the loser of a tap race needs the fresh view.
pub fn status_of(code: RoomErrorCode) -> u16 {
    match code {
        RoomErrorCode::NotFound => 404,
        RoomErrorCode::RoomFull | RoomErrorCode::AlreadyStarted => 409,
        RoomErrorCode::BadSession => 401,
        RoomErrorCode::BadRequest => 400,
        RoomErrorCode::Busy => 503,
    }
}

/// What a browser may send over the room's WebSocket. Only one thing: who it
/// is. A browser cannot set headers on a WebSocket and the token must never ride
/// in a URL (logs, history, `Referer`), so it is the first message instead.
/// Moves still go over HTTP, so a move has exactly one path.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "camelCase")]
#[ts(export)]
pub enum ClientMessage {
    Auth { token: String, since: u32 },
}

/// The session rides in a header, never a query string.
pub const SESSION_HEADER: &str = "x-kaboo-session";

/// A short, unambiguous room code — read aloud across a table. Both members of
/// every confusable pair (0/O, 1/I/L, E/3…) are left out.
pub const ROOM_CODE_ALPHABET: &str = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
pub const ROOM_CODE_LENGTH: usize = 4;

/// Mint a room code from an injected uniform [0, 1) generator.
pub fn make_room_code(rng: &mut dyn FnMut() -> f64) -> String {
    let alphabet: Vec<char> = ROOM_CODE_ALPHABET.chars().collect();
    (0..ROOM_CODE_LENGTH)
        .map(|_| alphabet[((rng() * alphabet.len() as f64).floor() as usize).min(alphabet.len() - 1)])
        .collect()
}

/// Accept a room code the way a human types it, and reduce it to canonical form.
///
/// It arrives lowercase, or with a hyphen written on a napkin, or with spaces.
/// Everything outside the alphabet is dropped rather than rejected: a code that
/// reduces to nothing simply will not be found. Look-alikes are NOT mapped onto
/// each other — inventing a mapping would silently send a player to another room.
pub fn normalize_room_code(raw: &str) -> String {
    raw.to_uppercase().chars().filter(|c| ROOM_CODE_ALPHABET.contains(*c)).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normalizes_a_code_the_way_a_human_typed_it() {
        assert_eq!(normalize_room_code(" ab-cd "), "ABCD");
        assert_eq!(normalize_room_code("o0il1e"), "E", "only E is in the alphabet");
        assert_eq!(normalize_room_code("x7y8"), "X7Y8");
    }

    #[test]
    fn mints_codes_only_from_the_alphabet() {
        let mut n = 0.0;
        let mut rng = || {
            n = (n + 0.37) % 1.0;
            n
        };
        for _ in 0..50 {
            let code = make_room_code(&mut rng);
            assert_eq!(code.len(), ROOM_CODE_LENGTH);
            assert!(code.chars().all(|c| ROOM_CODE_ALPHABET.contains(c)));
        }
        assert_eq!(make_room_code(&mut || 0.999_999_999), "9999");
    }

    #[test]
    fn maps_every_failure_to_its_status() {
        assert_eq!(status_of(RoomErrorCode::NotFound), 404);
        assert_eq!(status_of(RoomErrorCode::RoomFull), 409);
        assert_eq!(status_of(RoomErrorCode::AlreadyStarted), 409);
        assert_eq!(status_of(RoomErrorCode::BadSession), 401);
        assert_eq!(status_of(RoomErrorCode::BadRequest), 400);
        assert_eq!(status_of(RoomErrorCode::Busy), 503);
    }

    #[test]
    fn serializes_a_room_error_as_the_browser_reads_it() {
        let json = serde_json::to_value(room_error(RoomErrorCode::BadSession)).unwrap();
        assert_eq!(json["ok"], false);
        assert_eq!(json["code"], "E_BAD_SESSION");
        assert_eq!(json["message"], "That seat is not yours.");
    }

    #[test]
    fn parses_the_auth_message() {
        let msg: ClientMessage = serde_json::from_str(r#"{"type":"auth","token":"t","since":3}"#).unwrap();
        assert_eq!(msg, ClientMessage::Auth { token: "t".into(), since: 3 });
    }
}
